<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN']);$db=Database::connection();$q=trim((string)($_GET['q']??''));$s=$db->prepare("SELECT a.*,CONCAT(u.prenom,' ',u.nom) utilisateur FROM journal_audit a LEFT JOIN utilisateurs u ON u.id=a.utilisateur_id WHERE :q='' OR a.action LIKE :like_action OR a.entite LIKE :like_entite ORDER BY a.date_action DESC LIMIT 100");$like='%'.$q.'%';$s->execute(['q'=>$q,'like_action'=>$like,'like_entite'=>$like]);$rows=$s->fetchAll();$title='Audit';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><h1 class="h3">Journal d’audit</h1></div><form class="filter-bar"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Action ou entité"><button class="btn btn-dark">Rechercher</button></form><div class="card"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Date</th><th>Utilisateur</th><th>Action</th><th>Entité</th><th>Détails</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['date_action']) ?></td><td><?= e($r['utilisateur']) ?></td><td><?= e($r['action']) ?></td><td><?= e($r['entite'].' #'.$r['entite_id']) ?></td><td><?= e($r['details']) ?></td><td><?= e($r['adresse_ip']) ?></td></tr><?php endforeach ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
